//! Cross-language verification of PKCS#8 Ed25519 v1 (48 B), v2 ring (83 B),
//! and v2 RFC 8410 / OpenSSL (85 B) golden fixtures generated by WebCrypto /
//! Node.js in `testdata/pkcs8-ed25519-v2/`.

use std::collections::BTreeSet;
use std::path::PathBuf;

use base64::Engine as _;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use ring::rand::SystemRandom;
use ring::signature::{ED25519, Ed25519KeyPair, KeyPair as _, UnparsedPublicKey};
use serde_json::Value;
use spawn_node_proto::codec::{b64u, sha256_hex, unhex};
use spawn_node_proto::{PublicKey, SigningKey};

const PKCS8_V1_PREFIX: [u8; 16] = [
    0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20,
];
const PKCS8_V2_BODY: [u8; 14] = [
    0x02, 0x01, 0x01, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20,
];

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/pkcs8-ed25519-v2")
}

fn read(name: &str) -> Vec<u8> {
    std::fs::read(dir().join(name)).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn pkcs8_ed25519_v2_manifest_matches_all_fixtures() {
    let manifest = std::fs::read_to_string(dir().join("MANIFEST.sha256")).unwrap();
    let mut listed = BTreeSet::new();
    for line in manifest.lines() {
        let (expected, name) = line.split_once("  ").expect("manifest line");
        assert!(listed.insert(name.to_string()), "duplicate {name}");
        assert_eq!(
            sha256_hex(&read(name)),
            expected,
            "hash mismatch for {name}"
        );
    }
    let mut actual = BTreeSet::new();
    for entry in std::fs::read_dir(dir()).unwrap() {
        let name = entry.unwrap().file_name().into_string().unwrap();
        if name != "MANIFEST.sha256" {
            actual.insert(name);
        }
    }
    assert_eq!(listed, actual);
}

#[test]
fn pkcs8_ed25519_v2_golden_encodings_match_ring() {
    let v: Value = serde_json::from_slice(&read("vectors.json")).unwrap();
    assert_eq!(v["schema"], "pkcs8-ed25519-v2");
    let seed: [u8; 32] = unhex(v["seed_hex"].as_str().unwrap(), 64)
        .unwrap()
        .try_into()
        .unwrap();
    let signing = SigningKey::from_seed(&seed).unwrap();
    assert_eq!(
        signing.public_key().to_b64u(),
        v["pubkey_b64u"].as_str().unwrap()
    );
    assert_eq!(signing.public_key().key_id(), v["key_id"].as_str().unwrap());

    let msg = v["message"].as_str().unwrap().as_bytes();
    let expected_sig = v["signature_b64u"].as_str().unwrap();
    assert_eq!(signing.sign_b64u(msg), expected_sig);

    let spki = read("key.spki.der");
    assert_eq!(spki.len(), 44);
    assert_eq!(b64u(&spki), v["spki_der_b64u"].as_str().unwrap());
    assert_eq!(spki[12..44], signing.public_key().0);

    let v1 = read("key.v1.der");
    let v2_ring = read("key.v2-ring.der");
    let v2_rfc = read("key.v2-rfc8410.der");
    assert_eq!(v1.len(), 48);
    assert_eq!(&v1[..16], &PKCS8_V1_PREFIX);
    assert_eq!(&v1[16..48], &seed);

    assert_eq!(v2_ring.len(), 83);
    assert_eq!(&v2_ring[..2], &[0x30, 0x51]);
    assert_eq!(&v2_ring[2..16], &PKCS8_V2_BODY);
    assert_eq!(&v2_ring[16..48], &seed);
    assert_eq!(&v2_ring[48..51], &[0x81, 0x21, 0x00]);
    assert_eq!(&v2_ring[51..83], &signing.public_key().0);

    assert_eq!(v2_rfc.len(), 85);
    assert_eq!(&v2_rfc[..2], &[0x30, 0x53]);
    assert_eq!(&v2_rfc[2..16], &PKCS8_V2_BODY);
    assert_eq!(&v2_rfc[16..48], &seed);
    assert_eq!(&v2_rfc[48..53], &[0xa1, 0x23, 0x03, 0x21, 0x00]);
    assert_eq!(&v2_rfc[53..85], &signing.public_key().0);

    for (label, bytes) in [("v1", &v1), ("v2_ring", &v2_ring), ("v2_rfc8410", &v2_rfc)] {
        let spec = &v["formats"][label];
        assert_eq!(
            spec["len"].as_u64().unwrap(),
            u64::try_from(bytes.len()).unwrap()
        );
        assert_eq!(b64u(bytes), spec["der_b64u"].as_str().unwrap());
        assert_eq!(sha256_hex(bytes), spec["sha256_hex"].as_str().unwrap());
    }

    // ring accepts its own 83-byte v2 format and signs identically to WebCrypto
    let pair = Ed25519KeyPair::from_pkcs8(&v2_ring).unwrap();
    assert_eq!(pair.public_key().as_ref(), &spki[12..44]);
    let raw_sig = pair.sign(msg);
    assert_eq!(b64u(raw_sig.as_ref()), expected_sig);
    UnparsedPublicKey::new(&ED25519, &spki[12..44])
        .verify(msg, raw_sig.as_ref())
        .unwrap();

    // Fresh ring PKCS#8 generation matches the frozen v2_ring layout
    let rng = SystemRandom::new();
    let fresh = Ed25519KeyPair::generate_pkcs8(&rng).unwrap();
    let fresh_bytes = fresh.as_ref();
    assert_eq!(fresh_bytes.len(), 83);
    assert_eq!(&fresh_bytes[..2], &[0x30, 0x51]);
    assert_eq!(&fresh_bytes[2..16], &PKCS8_V2_BODY);
    assert_eq!(&fresh_bytes[48..51], &[0x81, 0x21, 0x00]);

    // Verify PublicKey::verify_b64u accepts the WebCrypto signature
    PublicKey(signing.public_key().0)
        .verify_b64u(msg, expected_sig)
        .unwrap();

    // Every reject vector fails strict length/OID checks
    let rejects: Value = serde_json::from_slice(&read("reject.json")).unwrap();
    for item in rejects.as_array().unwrap() {
        let raw = URL_SAFE_NO_PAD
            .decode(item["der_b64u"].as_str().unwrap())
            .unwrap();
        assert!(Ed25519KeyPair::from_pkcs8(&raw).is_err());
    }
}
